ssize_t decode_compact_pixels(size_t number_compact_pixels, const unsigned char* compact_pixels,
                              ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    ssize_t count = 0;
    size_t i = 0;
    size_t j = 0;

    while (i < number_compact_pixels && j < number_pixels) {
        switch (depth) {
            case 1:
                for (size_t k = 0; k < 8 && i < number_compact_pixels && j < number_pixels; ++k, ++i, ++j) {
                    pixels[j] = (compact_pixels[i] >> (7 - k)) & 0x01;
                }
                break;
            case 2:
                for (size_t k = 0; k < 4 && i < number_compact_pixels && j < number_pixels; ++k, ++i, ++j) {
                    pixels[j] = (compact_pixels[i] >> (6 - 2 * k)) & 0x03;
                }
                break;
            case 4:
                for (size_t k = 0; k < 2 && i < number_compact_pixels && j < number_pixels; ++k, ++i, ++j) {
                    pixels[j] = (compact_pixels[i] >> ((1 - k) * 4)) & 0x0F;
                }
                break;
            default:
                return -1; // Invalid depth
        }
    }

    return count;
}

ssize_t decode_pixel_data(size_t number_compact_pixels, const unsigned char* compact_pixels,
                            ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    size_t i = 0, j = 0;
    size_t compact_idx = 0;
    size_t output_idx = 0;

    switch (depth) {
        case 1: {
            while (compact_idx < number_compact_pixels && output_idx < number_pixels) {
                pixels[output_idx++] = compact_pixels[compact_idx] & 0x01 ? 1 : 0;
                compact_idx++;
            }
            break;
        }
        case 2: {
            while (compact_idx < number_compact_pixels && output_idx + 4 <= number_pixels) {
                pixels[output_idx++] = (compact_pixels[compact_idx] & 0x03);
                pixels[output_idx++] = (compact_pixels[compact_idx] >> 2) & 0x03;
                compact_idx++;
            }
            break;
        }
        case 4: {
            while (compact_idx < number_compact_pixels && output_idx + 2 <= number_pixels) {
                pixels[output_idx++] = compact_pixels[compact_idx] & 0x0F;
                pixels[output_idx++] = (compact_pixels[compact_idx] >> 4) & 0x0F;
                compact_idx++;
            }
            break;
        }
        default:
            return -1; // Invalid depth
    }
    return static_cast<ssize_t>(output_idx);
}

ssize_t decode_pixel_data(size_t number_compact_pixels, const unsigned char* compact_pixels, ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    size_t i = 0;
    size_t j = 0;
    unsigned char mask;

    switch (depth) {
        case 1:
            while (i < number_compact_pixels && j < number_pixels) {
                for (size_t bit = 0; bit < 8 && j < number_pixels; bit++) {
                    mask = (1 << (7 - bit)) & compact_pixels[i];
                    pixels[j++] = (mask != 0) ? 255 : 0;
                }
                i++;
            }
            break;
        case 2:
            while (i < number_compact_pixels && j < number_pixels) {
                for (size_t bit = 0; bit < 4 && j < number_pixels; bit++) {
                    mask = (3 << (6 - (bit * 2))) & compact_pixels[i];
                    pixels[j++] = (mask >> (6 - (bit * 2))) * 85;
                }
                i++;
            }
            break;
        case 4:
            while (i < number_compact_pixels && j < number_pixels) {
                for (size_t bit = 0; bit < 2 && j < number_pixels; bit++) {
                    mask = (15 << ((1 - bit) * 4)) & compact_pixels[i];
                    pixels[j++] = (mask >> ((1 - bit) * 4)) * 17;
                }
                i++;
            }
            break;
        default:
            return -1;
    }

    return (ssize_t)j;
}

